#[derive(Deserialize)]
#[serde(try_from = "RawOrder")]              // every parse must pass validation
pub struct Order { id: OrderId, customer: CustomerId }   // private fields
#[derive(Deserialize)]
pub struct RawOrder { customer: String }
impl TryFrom<RawOrder> for Order {
    type Error = DomainError;
    fn try_from(raw: RawOrder) -> Result<Self, DomainError> {
        if raw.customer.is_empty() { return Err(DomainError::MissingCustomer); }
        Ok(Order { id: OrderId::new(), customer: CustomerId::new(raw.customer)? })
    }
}
